const A='assets/';
const path=location.pathname;const page=path.includes('bed-bug-bordello')?'whitefield':path.includes('garland-gta')?'garland':'home';
const reviews=[
{name:'Danita',date:'October 7, 2026',score:'1.0',quote:'Reservation was cancelled the day of our arrival due to a pest problem.',context:'The guest says they were already on the way and did not get to stay.'},
{name:'Doris',date:'September 30, 2026',score:'7.0',quote:"I did enjoy my stay and would love to stay again",context:'Also reported a nonworking projector and bites from little black bugs, explicitly saying “Not bedbugs.”'},
{name:'Miyah',date:'September 20, 2026',score:'1.0',quote:'As soon as I walked in i seen roaches.',context:'The supplied review also alleges bedbugs and a nonworking master-bedroom shower. A property-response preview is visible; the full response was not supplied.'},
{name:'Chiquita',date:'September 17, 2026',score:'8.0',quote:'It was plenty of room for my friends and I to be comfortable.',context:'Also reported lock trouble and suspected bedbugs; the guest says a doctor confirmed the bites.'},
{name:'Thanh',date:'September 5, 2026',score:'7.0',quote:'Good location, large space, free parking. But bad smell room, bedbug, small cockroach.',context:'The supplied review includes both positive comments and cleanliness complaints.'},
{name:'Cole',date:'September 2024',score:'2',scale:'5',platform:'Airbnb',image:'garland/2_party_house.png',quote:'Place was noticeably dirty when entering. Entrance hadn’t been vacuumed, sticky stuff on the floor. The couch was ripped, there was wall damage - felt like a party house unsuitable for family stays.',context:'15 years on Airbnb · Rated 2 stars out of 5.'}
];
const videos=[['Shooting · supplied video 01','r2nPxOJlNd0'],['Shooting · supplied video 02','E4NYwe-brgI'],['Shooting · supplied video 03','LxeWDLwMIno'],['Sunday morning fight · supplied video','BuSnI4De5Sk'],['Grinder pump overflow · video 01','0qKOywS4RWo'],['Grinder pump overflow · video 02','USQtHn8AiHo'],['Guest conversation · video 01','obECa0K9oss'],['Guest conversation · video 02','9YM11YvgE54']];
const hero=(name,tag,description,img,link,label)=>`<div class="hero"><div><div class="eyebrow">${tag}</div><h1>${name}</h1><p class="intro">${description}</p><a class="button" href="${link}">${label} ↗</a>${page!=='home'?'<button class="share">Copy page link</button>':''}<p class="source">An independent neighbor-created parody. No bookings. Plenty of reading material.</p></div><img class="art" src="${A+img}" alt="Supplied parody artwork for ${name}"></div>`;
const gallery=(files)=>`<div class="gallery">${files.map(([file,caption])=>`<figure><button class="image-button" data-image="${A+file}" data-caption="${caption}"><img loading="lazy" src="${A+file}" alt="${caption}"></button><figcaption>${caption}</figcaption></figure>`).join('')}</div>`;
const reviewSection=()=>`<section id="reviews"><div class="eyebrow">The guest book</div><h2>What guests are saying.</h2><p>Six supplied guest reviews: five from Booking.com and one from Airbnb. Read the praise, the complaints, and the screenshots for yourself.</p><div class="review-shell"><div class="review-top"><span class="eyebrow">Guest reviews · September 2024 & September–October 2026</span><div class="controls"><button id="prev" aria-label="Previous review">←</button><button id="pause">Pause</button><button id="next" aria-label="Next review">→</button></div></div><div id="review-content"></div><div class="dots" aria-label="Choose review">${reviews.map((_,i)=>`<button data-slide="${i}" aria-label="Review ${i+1}"></button>`).join('')}</div></div><details><summary>Read the complete supplied review text</summary><pre id="review-text">Loading supplied text…</pre><a href="assets/whitefield/rev-ew_text_booking_com.txt">Open original text file</a></details><p class="note">Guest statements are reproduced from the supplied files and are not independent pest inspections. The reviews include mixed experiences; Doris explicitly says the bugs were not bedbugs.</p></section>`;
const featuredEvidence=()=>`<section class="featured-evidence" id="featured-evidence"><div class="eyebrow">Leave because of the bed bugs.dello</div><h2>The footage. The guest reviews.</h2><p class="intro">A Sunday morning fight and the supplied shooting footage, followed by the guests’ own review screenshots.</p><div class="video-grid">${[['Sunday morning fight','BuSnI4De5Sk'],['Shooting footage','LxeWDLwMIno']].map(([title,id])=>`<article class="video"><h3>${title}</h3><div class="video-screen"><iframe src="https://www.youtube-nocookie.com/embed/${id}" title="Featured ${title}" allow="fullscreen; picture-in-picture" allowfullscreen></iframe></div><a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">Watch on YouTube ↗</a></article>`).join('')}</div><p class="source">Videos supplied by the site creator and labeled according to their account.</p><div class="featured-review-heading"><div class="eyebrow">The guest photo reviews</div><h3>Bed Bug Bordello’s guest book.</h3><p>Five supplied Booking.com review screenshots, including reports of pests and mixed guest experiences. Select a screenshot to read it at full size.</p></div><div class="featured-reviews">${reviews.slice(0,5).map((r,i)=>`<figure><button class="image-button" data-image="${A}whitefield/review_${i+1}.png" data-caption="${r.name} · supplied ${r.platform||'Booking.com'} review"><img src="${A}whitefield/review_${i+1}.png" alt="${r.name} Booking.com review screenshot, ${r.date}"></button><figcaption><strong>${r.name} · ${r.score} / 10</strong><br>${r.date}<p>${r.context}</p></figcaption></figure>`).join('')}</div><p class="note">Guest accounts are reproduced from the supplied material. Doris explicitly says the bugs were not bedbugs.</p><a class="button secondary" href="bed-bug-bordello.html#reviews">Read the full review collection ↗</a></section>`;
const whitefield=()=>`${hero('Bed Bug<br>Bordello','01 / The Whitefield edition','Come for the getaway.<br>Stay for the guest book.','whitefield/whitefieldbed_bug_bordello.jpg','#reviews','Read the reviews')}<div class="strip"><span>A satirical name</span><span>Real supplied reviews</span><span>A neighbor’s account</span></div>${reviewSection()}<section><div class="eyebrow">Guest-uploaded material</div><h2>The less glamorous photo album.</h2><p class="note">Images supplied in the bedbug-pictures folder. These photographs alone do not establish species or the origin of any marks.</p>${gallery(['735112330.jpg','735112342.jpg','743427130.jpg'].map((f,i)=>['whitefield/bedbug_pictures/'+f,'Supplied guest image '+(i+1)]))}</section><section id="incidents"><div class="eyebrow">Beyond the listing</div><h2>What the neighbors report.</h2><p>The site creator reports a shooting and damage to their vehicle, lawn, and home. The following photographs and correspondence were supplied with that account.</p>${gallery([['whitefield/shooting/1.jpg','Shooting-related photograph 01'],['whitefield/shooting/2.jpg','Shooting-related photograph 02'],['whitefield/shooting/trunk.jpg','Vehicle trunk · supplied damage photograph'],['whitefield/shooting/muffler.webp','Vehicle muffler · supplied damage photograph']])}<div class="notice"><strong>The insurance correspondence</strong><p>The supplied March 3, 2026 letter records a reported September 14, 2025 shooting loss. It denies host liability, says police did not identify the shooters, and states that the host was not involved. This document is included as correspondence, not as a finding of wrongdoing by the host.</p><details><summary>View the supplied insurance letter</summary>${gallery([['whitefield/shooting/denied_insurance_claim.jpg','Supplied insurance denial letter · March 3, 2026']])}</details></div><h3>Trespassing on our lawn.</h3><p class="note">People trespassing and driving on our lawn caused this damage, according to our account. These are our photographs of the lawn damage.</p>${gallery([3,4,5].map(i=>['whitefield/lawn_damage/'+i+'.jpg','Lawn-damage photograph '+(i-2)]))}</section><section id="videos"><div class="eyebrow">The neighborhood watch list</div><h2>Not the vacation highlight reel.</h2><p>Shooting footage, a reported fight, grinder-pump overflow, and guest conversations, grouped using the labels in the supplied video file.</p><p class="note">Video players are shown below, or you can open the original videos on YouTube. Video content and incident labels have not been independently verified.</p><div class="video-grid">${videos.map(([title,id])=>`<article class="video"><h3>${title}</h3><div class="video-screen"><iframe src="https://www.youtube-nocookie.com/embed/${id}" title="${title}" allow="fullscreen; picture-in-picture" allowfullscreen></iframe></div><a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">Watch on YouTube ↗</a></article>`).join('')}</div><p><a href="assets/whitefield/youtube_videos.txt">Original video-link file ↗</a></p></section><section><div class="eyebrow">Additional supplied material</div><h2>The party-house file.</h2>${gallery([['whitefield/1_party_house.png','Additional Whitefield party-house material · supplied image']])}</section>`;
const garland=()=>`${hero('Garland GTA','02 / The Garland edition','Same house. Different party.<br>The neighborhood gets the sequel.','garland/garland_gta.jpg','#gallery','Explore the photo file')}<div class="strip"><span>Parody artwork</span><span>Supplied sanitation photos</span><span>The smaller dossier</span></div><section id="gallery"><div class="eyebrow">The morning after</div><h2>Leave only memories.<br>And a Lot of Trash!</h2><p>The supplied Garland folder contains parody artwork, a party-house image, and two sanitation photographs with June 18, 2026 in their filenames.</p>${gallery([['garland/1_party_house.png','Additional Garland party-house material · supplied image'],['garland/sanitation_trash_issue_2026-06-18.jpg','Sanitation photograph 01 · filename dated June 18, 2026'],['garland/sanitation_trash_issue_2026-06-18_1.jpg','Sanitation photograph 02 · filename dated June 18, 2026']])}<p class="note">No Garland review text or incident videos were supplied. The dramatic scenes and slogans in the Garland GTA illustration are parody, not documentary photographs or verified incident claims.</p></section>`;
const home=()=>`${hero('Wish you<br>weren’t here.','The neighbor’s travel guide','Two rentals. One neighborhood.<br>A satirical travel guide to the other side of the vacation brochure.','whitefield/whitefieldbed_bug_bordello.jpg','#properties','Choose your adventure')}<div class="strip"><span>Independent neighborhood parody</span><span>Guest reviews & supplied documentation</span><span>No reservations accepted</span></div><section id="properties"><div class="eyebrow">Our carefully uncurated collection</div><h2>Pick your plot twist.</h2><div class="grid"><article class="property"><a href="bed-bug-bordello.html"><img src="${A}whitefield/whitefieldbed_bug_bordello.jpg" alt="Bed Bug Bordello parody artwork"></a><p class="number">01 / WHITEFIELD</p><h3>Bed Bug Bordello</h3><p>A guest book with a storyline. Browse six reviews, supplied damage photos, insurance correspondence, and eight embedded videos.</p><a class="button" href="bed-bug-bordello.html">Read the full story ↗</a></article><article class="property"><a href="garland-gta.html"><img src="${A}garland/garland_gta.jpg" alt="Garland GTA parody artwork"></a><p class="number">02 / GARLAND</p><h3>Garland GTA</h3><p>Same house. Different party. A shorter photo-led edition featuring the supplied artwork and sanitation material.</p><a class="button" href="garland-gta.html">Explore Garland GTA ↗</a></article></div></section><section><div class="eyebrow">Behind the brochure</div><h2>A joke with a paper trail.</h2><p class="intro">This is a neighbor’s parody project about the experience of living beside short-term rentals. The nicknames and travel-brochure copy are satire; the guest reviews and documentation are presented with their sources and limits.</p><p class="note">Neither page is a rental listing. This project is not affiliated with Airbnb, Booking.com, any property owner, or the Grand Theft Auto franchise. Parody illustrations should not be mistaken for photographs of actual events.</p></section>`;
document.title=page==='home'?"The Neighbor’s Travel Guide":page==='whitefield'?'Bed Bug Bordello | The Neighbor’s Travel Guide':'Garland GTA | The Neighbor’s Travel Guide';
document.querySelector('#app').innerHTML=`<header><a class="brand" href="index.html">The Neighbor’s <span>Travel Guide.</span></a><nav aria-label="Main navigation"><a href="index.html">The collection</a><a href="bed-bug-bordello.html">Whitefield</a><a href="garland-gta.html">Garland</a></nav></header><main>${page==='home'||page==='whitefield'?featuredEvidence():''}${page==='home'?home():page==='whitefield'?whitefield():garland()}</main><footer><strong>Satire up front. Sources underneath.</strong><p>Independent neighbor-created commentary. Reports and reviews reflect their stated sources; disputed claims are not findings of liability. Parody names and illustrations are creative material. No affiliation or endorsement is implied.</p><nav class="footer-links" aria-label="Related pages">${page==='whitefield'?'<a href="garland-gta.html">Visit Garland GTA ↗</a>':page==='garland'?'<a href="bed-bug-bordello.html">Visit Bed Bug Bordello ↗</a>':''}<a href="https://michaelwoodc.github.io/stvr-info-page/owners/cozy_corner_rentals/cozy_corner_rentals.html">Cozy Corner Rentals info page ↗</a><a href="index.html">Back to the collection ↑</a></nav></footer>`;
let slide=0,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches;
function renderReview(){const r=reviews[slide];document.querySelector('#review-content').innerHTML=`<div class="review"><button class="image-button" data-image="${A+(r.image||`whitefield/review_${slide+1}.png`)}" data-caption="${r.name} · supplied ${r.platform||'Booking.com'} review"><img src="${A+(r.image||`whitefield/review_${slide+1}.png`)}" alt="Supplied review screenshot ${slide+1}, ${r.name}"></button><div><span class="eyebrow">${r.score} / ${r.scale||'10'} · ${r.name}</span><blockquote>“${r.quote}”</blockquote><p>${r.context}</p><p class="source">${r.platform||'Booking.com'} · Reviewed ${r.date}<br>Screenshot ${slide+1} of ${reviews.length} · Click to enlarge</p></div></div>`;document.querySelectorAll('[data-slide]').forEach((el,i)=>el.classList.toggle('active',i===slide));document.querySelector('#pause').textContent=playing?'Pause':'Play';}
if(page==='whitefield'){const timer=createSlideshowTimer(document.querySelector('.review-shell'),()=>{slide=(slide+1)%reviews.length;renderReview()},()=>playing);renderReview();document.querySelector('#prev').onclick=()=>{slide=(slide-1+reviews.length)%reviews.length;renderReview();timer.reset()};document.querySelector('#next').onclick=()=>{slide=(slide+1)%reviews.length;renderReview();timer.reset()};document.querySelector('#pause').onclick=()=>{playing=!playing;renderReview();timer.reset()};document.querySelectorAll('[data-slide]').forEach(el=>el.onclick=()=>{slide=Number(el.dataset.slide);renderReview();timer.reset()});fetch(A+'whitefield/rev-ew_text_booking_com.txt').then(r=>{if(!r.ok)throw Error();return r.text()}).then(t=>document.querySelector('#review-text').textContent=t+'\n\nCole\n15 years on Airbnb\nRating: 2 stars out of 5\nSeptember 2024\n'+reviews[reviews.length-1].quote).catch(()=>document.querySelector('#review-text').textContent='Use the original text-file link below to read the supplied reviews.');}
document.addEventListener('click',e=>{const el=e.target.closest('[data-image]');if(el){const d=document.querySelector('#viewer');d.querySelector('img').src=el.dataset.image;d.querySelector('img').alt=el.dataset.caption;d.querySelector('p').textContent=el.dataset.caption;d.showModal()}});
document.querySelector('.close').onclick=()=>document.querySelector('#viewer').close();document.querySelector('#viewer').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});document.querySelector('.share')?.addEventListener('click',async e=>{try{await navigator.clipboard.writeText(location.href);e.target.textContent='Link copied ✓'}catch{e.target.textContent='Copy this page’s address from your browser'}});
